# -*- coding: utf-8 -*-
import sys
F = sys.argv[1]
s = open(F, encoding='utf-8').read()
Y = 'https://ya.ru/archive/catalog/'
old = '    <section>\n      <h3>Найдено 31.10.2026</h3>'
assert s.count(old) == 1
new = ('    <section>\n      <h3>Найдено 02.11.2026</h3>\n      <ul>\n'
 '        <li>Соколовы: <a href="' + Y + 'e979bb5b-8b2d-4005-ae1b-3767bb0c11b3/9">Сенатские объявления 1835 (Д. И.)</a>, <a href="' + Y + '37ca1e70-f45b-489c-9b93-7c7d4a0c47eb/2">1857 (И. Д., Пырятинка)</a>; <a href="' + Y + '0a0ea694-0843-4b3b-95ba-2e707f68793d/34">ЦГА Москвы ф.2125 оп.3 д.224 ск.34 — справка о Митрофане 1880</a>; <a href="' + Y + '94f03d92-b420-4fcb-b332-daccd1129682/74">ф.2122 оп.3 д.218 ск.74 — копия рождения С. С. 1887</a>; <a href="' + Y + '5ccd31f0-8538-4d53-9359-33a52721dec0/291">ф.203 оп.782 д.179 ск.291 — брак С. С. 1910</a>; <a href="https://el.archive-bryansk.ru/archives/gabo/inventories/417835164">ГАБО ф.247 оп.1 — опись метрик церквей Карачевского у.</a></li>\n'
 '        <li>Бедаревы: <a href="' + Y + '85ebaabe-6fd7-41ce-ad20-7843617e0702/114">Фива 1897 (ф.60 оп.1 д.657 ск.114)</a>; <a href="' + Y + '3347c189-e4b0-4549-baf3-feb31396c927/53">Серафим 1905, 2-й экземпляр (оп.5 д.31 ск.53)</a>; <a href="' + Y + '01bc0367-b9e8-41e9-a143-5f333d189fdb/247">Наталия 1881/82, крёстная Надежда Гри[горьева] (оп.5 д.1 ск.247)</a></li>\n'
 '        <li>Елескины: <a href="' + Y + 'bb2430b0-0121-44ef-a042-c1771c0d4b39/142">смерть В. Д. Елескина 1917 (оп.6 д.63 ск.142)</a>; проверено без Ольги: оп.6 д.70 (1913), д.259 (1916–18), д.385 (Челухоево 1918), д.46 (1912 и 1914), оп.4 д.394 (1908–09)</li>\n'
 '        <li>Выдрины: ИАОО ф.16 оп.5 и оп.6 — Песчанская и Павлодарская церкви 1869–1889, все записи Выдриных (однофамильцы, связь не установлена)</li>\n'
 '        <li>Федосовы: <a href="https://gwar.mil.ru/heroes/chelovek_donesenie13463176/">GWAR — Федосеев Иван, Рождественская вол.</a> (связь слабая); склейка «Пролейки» на Памяти народа — запись Федорова Я. В., не наш; наградные листы А. Ф. Федосова — домашний адрес пуст или скрыт</li>\n'
 '        <li>Фраер: <a href="https://www.blackseagr.org/research_church_odessa.html">BSGR — метрики Фрейденталя 1902–1913</a>, <a href="https://hfdr.de/wp-content/uploads/2023/10/Repressierten_1930-1950_im_Odessa-Gebiet_6618.pdf">репрессированные немцы Одесской обл.</a>; без результата — reabit.org.ua, «Поморский мемориал», DAI Wygoda</li>\n'
 '      </ul>\n    </section>\n\n' + old)
s = s.replace(old, new)
open(F, 'w', encoding='utf-8').write(s)
print('ok')
